/*
 * Handlebars AST interpreter that never evals.
 *
 * Rendering happens in two phases. `build` walks the AST once and returns a
 * tree of closures, one per node, each specialized to what that node is. The
 * tree is cached per Program, so a template pays for the walk once no matter
 * how often it renders, and rendering is then just calling the root closure
 * with a frame.
 *
 * Async is carried by `Pending`. Only a call out to user code can be pending,
 * so only those results are wrapped (see `invoked`), and `chain`/`runFrom`
 * defer the rest of the work when one shows up. A render that invokes nothing
 * async never allocates a promise.
 */

// consumers compile this out of node_modules, where their tsconfig `include`
// does not reach and only a triple-slash reference pulls in the augmentation.
// eslint-disable-next-line @typescript-eslint/triple-slash-reference
/// <reference path="./types/handlebars-parser.d.ts" />
import { parse, Exception } from '@handlebars/parser'
import type { AST as Hbs } from '@handlebars/parser'
import {
  createFrame,
  isArray,
  // aliased because each needs a cast below
  isFunction as rawIsFunction,
  isMap as rawIsMap,
  isSet as rawIsSet,
  escapeExpression as rawEscapeExpression,
  extend as rawExtend,
} from '../lib/handlebars/utils.js'
import {
  createProtoAccessControl,
  resultIsAllowed,
} from '../lib/handlebars/internal/proto-access.js'
import { noop as rawNoop } from '../lib/handlebars/runtime.js'
import { registerDefaultHelpers } from '../lib/handlebars/helpers.js'
import logger from '../lib/handlebars/logger.js'
import AST from '../lib/handlebars/compiler/ast.js'

// cast once here.
// Plain-JS inference would hand a loose type to this file and to anyone
// importing it.
const escapeExpression = rawEscapeExpression as (value: unknown) => string
// `extend` is really variadic (it reads `arguments`), but inference sees only
// its one declared parameter
const extend = rawExtend as <T extends object>(
  obj: T,
  ...sources: unknown[]
) => T
// the vendored guards infer as `=> boolean`, so they narrow nothing and every
// call site has to cast the value it just checked. Typed once as predicates.
const isFunction = rawIsFunction as (value: unknown) => value is Helper
const isMap = rawIsMap as (value: unknown) => value is Map<unknown, unknown>
const isSet = rawIsSet as (value: unknown) => value is Set<unknown>

// an empty program body
const noopProgram = rawNoop as ProgramFn

// wraps a thenable returned by user code. Assigned separately rather than as a
// parameter property, which emits code and breaks type stripping.
class Pending {
  readonly promise: Promise<unknown>

  constructor (promise: Promise<unknown>) {
    this.promise = promise
  }
}

type Rendered = string | Pending
type NodeFn = (frame: Frame) => Rendered
type ValueFn = (frame: Frame) => unknown

// a thenable returned by a call is pending.
// One that merely sits in the template data is not, and stringifies to
// "[object Promise]". Adopted rather than chained onto, since a thenable's
// `then` may return nothing.
function invoked (result: unknown): unknown {
  return result != null && typeof (result as { then?: unknown }).then === 'function'
    ? new Pending(Promise.resolve(result))
    : result
}

// lets a Pending be returned from inside a .then(), so the promise machinery
// flattens it instead of resolving to the wrapper
function unwrap (value: unknown): unknown {
  return value instanceof Pending ? value.promise : value
}

// every composite operation routes through this, so deferral lives in one
// place. Generic in both directions, so a caller keeps the resolved type on the
// way in and gets `R | Pending` back rather than having to cast the result.
function chain<T, R> (
  value: T | Pending,
  then: (resolved: T) => R
): R | Pending {
  if (value instanceof Pending) {
    return new Pending(value.promise.then((resolved) => unwrap(then(resolved as T))))
  }
  return then(value)
}

// sequential loop that can suspend. it resumes the remainder rather than
// restarting, which would re-run steps that already had side effects.
function runFrom (
  start: number,
  count: number,
  step: (i: number) => unknown,
  onValue: (i: number, value: unknown) => void
): Pending | undefined {
  for (let i = start; i < count; i++) {
    const value = step(i)
    if (value instanceof Pending) {
      const at = i
      return new Pending(value.promise.then((resolved) => {
        onValue(at, resolved)
        return unwrap(runFrom(at + 1, count, step, onValue))
      }))
    }
    onValue(i, value)
  }
  return undefined
}

// program bodies render constantly, so the synchronous path here avoids the two
// closures runFrom would need. Delegating to it instead measured several
// percent slower overall, so the duplication stays.
function renderAll (nodes: NodeFn[], frame: Frame): Rendered {
  const count = nodes.length
  let out = ''
  for (let i = 0; i < count; i++) {
    const value = nodes[i](frame)
    if (value instanceof Pending) {
      const at = i
      return new Pending(value.promise.then((resolved) => {
        out += (resolved as string) || ''
        const rest = runFrom(
          at + 1,
          count,
          (j) => nodes[j](frame),
          (_j, v) => { out += (v as string) || '' }
        )
        return rest ? rest.promise.then(() => out) : out
      }))
    }
    out += (value as string) || ''
  }
  return out
}

function settle (value: Rendered): string | Promise<string> {
  return value instanceof Pending
    ? (value.promise as Promise<string>)
    : value
}

type DataFrame = Record<string, unknown>

type LookupProperty = (parent: unknown, name: string) => unknown

interface ProgramFnOptions {
  data?: DataFrame;
  blockParams?: unknown[];
}

// calling these can produce a pending result, which a helper that only
// `return options.fn(this)` passes straight through
type ProgramFn = ((context?: unknown, fnOptions?: ProgramFnOptions) => string | Promise<string>) & {
  blockParams?: number;
}

type Helper = (this: unknown, ...args: unknown[]) => unknown
type HelpersMap = Record<string, Helper>

function asCallable (value: unknown): Helper | undefined {
  return isFunction(value) ? value : undefined
}

// options arrive as `unknown` through the untyped registry
function asHelperOptions (value: unknown): HelperOptions | undefined {
  return value != null && typeof value === 'object'
    ? (value as HelperOptions)
    : undefined
}

// spreads the caller's runtime options in, so a function partial sees them the
// way it would upstream. Nothing here reads them.
interface PartialCallOptions {
  helpers?: HelpersMap;
  partials?: PartialsMap;
  data?: DataFrame;
  [key: string]: unknown;
}

type PartialFn = (context: unknown, options?: PartialCallOptions) => string | Promise<string>
type Partial = PartialFn | string
type PartialsMap = Readonly<Record<string, Partial>>

// registered through the vendored entry point so the set can't drift from lib/.
// The object passed in is upstream's registration interface.
const defaultHelpers: HelpersMap = {}
registerDefaultHelpers({
  helpers: defaultHelpers,
  registerHelper (name: string, fn: Helper) {
    defaultHelpers[name] = fn
  },
  log: logger.log,
})

// the vendored `each` accumulates with `ret = ret + fn(...)`, which silently
// breaks on an async block body. Overwriting the entry also redirects
// blockHelperMissing, which forwards implicit array blocks to it.
defaultHelpers.each = nativeEach

interface RuntimeOptions {
  // an already-built frame only, propagated from a parent render so @root and
  // @index survive the boundary
  data?: DataFrame;
  helpers?: HelpersMap;
  partials?: PartialsMap;
}

interface HelperOptions {
  name: string | null;
  hash: Record<string, unknown>;
  data: DataFrame;
  // block invocations only, since helpers branch on `options.fn` to tell block
  // from inline usage
  fn?: ProgramFn;
  inverse?: ProgramFn;
  lookupProperty: LookupProperty;
}

// block param names are gone from the frame.
// Build resolves each reference to a (depth, slot) pair, so only the values
// travel at render time.
interface Frame {
  context: unknown;
  data: DataFrame;
  depths: unknown[];
  helpers: HelpersMap;
  partials: PartialsMap;
  blockParamValues: unknown[][];
  lookupProperty: LookupProperty;
  options: RuntimeOptions;
}

// every frame but the root is its parent with a few fields replaced. A literal
// rather than a spread keeps every frame on one hidden class.
function derive (
  frame: Frame, context: unknown, data: DataFrame,
  depths: unknown[], partials: PartialsMap, blockParamValues: unknown[][]
): Frame {
  return {
    context, data, depths, helpers: frame.helpers, partials,
    blockParamValues, lookupProperty: frame.lookupProperty, options: frame.options,
  }
}

// the shipped AST types inherit `.type` from their base interface instead of
// declaring their own, so fix that up locally to let a `switch` discriminate
interface DecoratorBlockNode extends Omit<Hbs.DecoratorBlock, 'type'> {
  type: 'DecoratorBlock';
}
interface DecoratorNode extends Omit<Hbs.Decorator, 'type'> {
  type: 'Decorator';
}

type StatementNode =
  | Hbs.ContentStatement
  | Hbs.MustacheStatement
  | Hbs.BlockStatement
  | Hbs.PartialStatement
  | Hbs.PartialBlockStatement
  | DecoratorBlockNode
  | DecoratorNode
  | Hbs.CommentStatement

type ExpressionHolder = Hbs.MustacheStatement | DecoratorNode | Hbs.SubExpression

// shared stand-ins for "the caller passed none". Never written to.
const emptyHelpers: HelpersMap = {}
const emptyPartials: PartialsMap = {}
const emptyValues: unknown[] = []
const emptyScopes: BlockParamScopes = []

// ---------------------------------------------------------------------------
// Prototype access
// ---------------------------------------------------------------------------

// upstream's defaults, built once and never reconfigurable. Passing `{}` leaves
// both defaultValues undefined, which is what keeps the one-time warning on a
// denied member.
// An explicit false would deny silently.
const defaultProtoAccess = createProtoAccessControl({})

function defaultLookupProperty (parent: unknown, name: string): unknown {
  if (parent == null) {
    return undefined
  }
  if (isMap(parent)) {
    return parent.get(name)
  }
  const result = (parent as Record<string, unknown>)[name]
  if (result == null) {
    return result
  }
  if (Object.prototype.hasOwnProperty.call(parent, name)) {
    return result
  }
  if (resultIsAllowed(result, defaultProtoAccess, name)) {
    return result
  }
  return undefined
}

// everything about a path reference that doesn't depend on the frame, so the
// regexes and the block param search run once per node
interface PathPlan {
  node: Hbs.PathExpression;
  data: boolean;
  parts: string[];
  depth: number;
  original: string;
  // one part, unscoped, depth 0, not @data, so it may name a helper
  simple: boolean;
  // block params are lexically scoped, so the slot is known at build time
  blockParam: { depth: number; idx: number } | null;
}

// innermost scope first, mirroring how frame.blockParamValues is stacked
type BlockParamScopes = readonly (readonly string[])[]

function findBlockParamSlot (
  scopes: BlockParamScopes,
  name: string
): { depth: number; idx: number } | null {
  for (let depth = 0; depth < scopes.length; depth++) {
    const idx = scopes[depth].indexOf(name)
    if (idx >= 0) {
      return { depth, idx }
    }
  }
  return null
}

// the grammar allows a literal where the AST types promise a PathExpression
// (`{{#true}}`), so rewrite it and let the build see only the two real cases
function normalizePath (
  path: Hbs.PathExpression | Hbs.SubExpression | Hbs.Literal
): Hbs.PathExpression | Hbs.SubExpression {
  // a SubExpression has no `parts` either, so it has to be excluded by type
  // rather than by shape
  if (path && path.type !== 'PathExpression' && path.type !== 'SubExpression') {
    const literal = path as Hbs.Literal & { original?: unknown }
    return {
      type: 'PathExpression',
      data: false,
      depth: 0,
      parts: [String(literal.original)],
      original: String(literal.original),
      loc: literal.loc,
    } as Hbs.PathExpression
  }
  // Literal declares `.type` as the loose base string, so the checks above
  // narrow nothing and the cast has to say what they proved
  return path as Hbs.PathExpression | Hbs.SubExpression
}

function planPath (path: Hbs.PathExpression, scopes: BlockParamScopes): PathPlan {
  const parts = (path.parts || []) as string[]
  const name = parts[0]
  if (path.depth) {
    sawDepthedPath = true
  }
  const scoped = AST.helpers.scopedId(path)
  // reruns scopedId's regex, but at build time, and defers the rule to upstream
  const simple =
    path.type === 'PathExpression' && !path.data && AST.helpers.simpleId(path)

  const eligible =
    !path.data && !path.depth && !!name && name !== 'this' && name !== '.' && !scoped

  return {
    node: path,
    data: !!path.data,
    parts,
    depth: path.depth || 0,
    original: path.original,
    simple,
    blockParam: eligible ? findBlockParamSlot(scopes, name) : null,
  }
}

function resolvePlan (plan: PathPlan, frame: Frame): unknown {
  if (plan.data) {
    return lookupData(frame, plan.parts, plan.depth)
  }

  const parts = plan.parts

  if (plan.blockParam) {
    let result = frame.blockParamValues[plan.blockParam.depth][plan.blockParam.idx]
    for (let i = 1; i < parts.length; i++) {
      if (result == null) {
        return undefined
      }
      result = frame.lookupProperty(result, parts[i])
    }
    return result
  }

  const ctx = plan.depth ? frame.depths[plan.depth] ?? null : frame.context

  if (!parts.length || parts[0] === '.') {
    return ctx
  }

  if (ctx == null) {
    return undefined
  }

  let result: unknown = ctx
  for (const part of parts) {
    if (result == null) {
      return undefined
    }
    result = frame.lookupProperty(result, part)
  }

  return result
}

function lookupData (frame: Frame, parts: string[], depth: number): unknown {
  let d: unknown = frame.data
  for (let i = 0; i < depth; i++) {
    d = d && (d as DataFrame)._parent
  }
  if (!parts.length) {
    return d
  }
  let result: unknown = d
  // every part goes through lookupProperty.
  // @root reaches back into user context, so raw access here would bypass
  // prototype-access control.
  for (const part of parts) {
    if (result == null) {
      return undefined
    }
    result = frame.lookupProperty(result, part)
  }
  return result
}

// reads through both maps instead of merging a copy per render. The guards keep
// template-controlled names off Object.prototype, and an own key holding
// `undefined` still shadows the builtin.
function findHelper (frame: Frame, name: string): Helper | undefined {
  // the one exception to caller-first.
  // A passed `each` must not shadow ours.
  if (name === 'each') {
    return defaultHelpers.each
  }
  if (Object.prototype.hasOwnProperty.call(frame.helpers, name)) {
    return frame.helpers[name]
  }
  if (Object.prototype.hasOwnProperty.call(defaultHelpers, name)) {
    return defaultHelpers[name]
  }
  return undefined
}

// always present in defaultHelpers, but the caller may have overridden either
function missingHelper (
  frame: Frame,
  name: 'helperMissing' | 'blockHelperMissing'
): Helper {
  const helper = findHelper(frame, name)
  if (!helper) {
    // reachable by passing `{ helperMissing: undefined }`. Upstream reaches the
    // same state and dies on `undefined.call`, so keep the TypeError but name
    // the cause.
    throw new TypeError('The "' + name + '" helper is not a function')
  }
  return helper
}

// a template may not name helperMissing/blockHelperMissing itself
function lookupHelper (frame: Frame, name: string | null): Helper | undefined {
  if (name === 'helperMissing' || name === 'blockHelperMissing') {
    throw new Exception('Missing helper: "' + name + '"')
  }
  return name ? findHelper(frame, name) : undefined
}

// params and hash values compiled to closures, hash keys hoisted out
interface CallPlan {
  params: ValueFn[];
  hashKeys: string[];
  hashValues: ValueFn[];
}

function planCall (
  params: Hbs.Expression[] | undefined,
  hash: Hbs.Hash | null | undefined,
  scopes: BlockParamScopes
): CallPlan {
  const pairs = hash ? hash.pairs : []
  return {
    params: (params || []).map((param) => buildValue(param, scopes)),
    hashKeys: pairs.map((pair) => pair.key),
    hashValues: pairs.map((pair) => buildValue(pair.value, scopes)),
  }
}

function buildHelperOptions (
  name: string | null,
  hash: Record<string, unknown>,
  frame: Frame,
  fn?: ProgramFn,
  inverse?: ProgramFn
): HelperOptions {
  const options: HelperOptions = {
    name,
    hash,
    data: frame.data,
    lookupProperty: frame.lookupProperty,
  }
  // conditional so inline calls don't carry the keys at all, matching the
  // options literal compiled Handlebars emits
  if (fn) {
    options.fn = fn
  }
  if (inverse) {
    options.inverse = inverse
  }
  return options
}

// never shared, since helpers receive it and may mutate it
function runHash (plan: CallPlan, frame: Frame): Record<string, unknown> | Pending {
  const hash: Record<string, unknown> = {}
  if (!plan.hashKeys.length) {
    return hash
  }
  const pending = runFrom(
    0,
    plan.hashValues.length,
    (i) => plan.hashValues[i](frame),
    (i, value) => { hash[plan.hashKeys[i]] = value }
  )
  return pending ? new Pending(pending.promise.then(() => hash)) : hash
}

function runCall (
  plan: CallPlan,
  helper: Helper,
  name: string | null,
  frame: Frame,
  fn?: ProgramFn,
  inverse?: ProgramFn
): unknown {
  const params = plan.params
  const count = params.length
  // options goes on the end of the same array, sized for that slot up front so
  // the store never grows it
  const args: unknown[] = new Array(count + 1)

  // inlined like renderAll's loop, so a call that suspends nowhere allocates
  // no closures
  for (let i = 0; i < count; i++) {
    const value = params[i](frame)
    if (value instanceof Pending) {
      const at = i
      return new Pending(value.promise.then((resolved) => {
        args[at] = resolved
        const rest = runFrom(
          at + 1,
          count,
          (j) => params[j](frame),
          (j, v) => { args[j] = v }
        )
        const done = (): unknown =>
          unwrap(applyCall(plan, helper, name, frame, args, count, fn, inverse))
        return rest ? rest.promise.then(done) : done()
      }))
    }
    args[i] = value
  }

  return applyCall(plan, helper, name, frame, args, count, fn, inverse)
}

// the params are in place, so only the hash is left.
// A hashless call cannot suspend here, so it skips runHash and chain.
function applyCall (
  plan: CallPlan,
  helper: Helper,
  name: string | null,
  frame: Frame,
  args: unknown[],
  count: number,
  fn?: ProgramFn,
  inverse?: ProgramFn
): unknown {
  if (!plan.hashKeys.length) {
    // still a fresh object, since helpers receive it and may mutate it
    args[count] = buildHelperOptions(name, {}, frame, fn, inverse)
    return invoked(helper.apply(frame.context, args))
  }
  return chain(runHash(plan, frame), (hash) => {
    args[count] = buildHelperOptions(name, hash, frame, fn, inverse)
    return invoked(helper.apply(frame.context, args))
  })
}

// plain context lookup. A function in the data is called with no arguments,
// unlike an ambiguous simple id, whose lambda gets an options object.
function buildLookup (plan: PathPlan): ValueFn {
  return (frame) => {
    const value = resolvePlan(plan, frame)
    const lambda = asCallable(value)
    return lambda ? invoked(lambda.call(frame.context)) : value
  }
}

function buildValue (node: Hbs.Expression, scopes: BlockParamScopes): ValueFn {
  switch (node.type) {
    case 'PathExpression':
      return buildLookup(planPath(node as Hbs.PathExpression, scopes))
    case 'SubExpression':
      return buildExpression(node as Hbs.SubExpression, scopes)
    case 'StringLiteral':
    case 'NumberLiteral':
    case 'BooleanLiteral': {
      const value = (node as Hbs.StringLiteral | Hbs.NumberLiteral | Hbs.BooleanLiteral).value
      return () => value
    }
    case 'UndefinedLiteral':
      return () => undefined
    case 'NullLiteral':
      return () => null
    default:
      // thrown when reached, so an unknown node in a dead branch stays harmless
      return () => {
        throw new Exception('Unknown value type: ' + node.type, node)
      }
  }
}

// the path is itself a subexpression, so resolve it and call whatever comes back
function buildSubExpressionCall (
  path: Hbs.SubExpression,
  call: CallPlan,
  scopes: BlockParamScopes
): ValueFn {
  const inner = buildExpression(path, scopes)
  // a SubExpression carries no `.original` of its own, so name the path it
  // wraps, which is what the template actually spells
  const original = (path.path as Hbs.PathExpression | undefined)?.original
  return (frame) =>
    chain(inner(frame), (helperFn) => {
      const helper = asCallable(helperFn)
      if (!helper) {
        throw new Exception(
          'The path ' + original + ' did not return a function',
          path
        )
      }
      return runCall(call, helper, null, frame)
    })
}

// arguments are present, so this is definitely a call.
// A helper, else a callable found in the context, else helperMissing.
function buildCall (plan: PathPlan, call: CallPlan, name: string | null): ValueFn {
  return (frame) => {
    if (name) {
      const helper = lookupHelper(frame, name)
      if (helper) {
        return runCall(call, helper, name, frame)
      }
    }
    const contextValue = resolvePlan(plan, frame)
    const callable = asCallable(contextValue)
    if (callable) {
      return runCall(call, callable, name, frame)
    }
    // calling a non-function would throw a TypeError, so raise something
    // readable
    if (contextValue != null) {
      throw new Exception(
        '"' + (name || plan.original) + '" is not a function',
        plan.node
      )
    }
    return runCall(
      call,
      missingHelper(frame, 'helperMissing'),
      name || plan.original,
      frame
    )
  }
}

// no arguments, so the name is ambiguous between a helper, a lambda in the
// context and a plain value. Helpers take precedence.
function buildAmbiguous (plan: PathPlan, name: string | null): ValueFn {
  return (frame) => {
    const helper = lookupHelper(frame, name)
    if (helper) {
      return runCall(noArgs, helper, name, frame)
    }
    const value = resolvePlan(plan, frame)
    const lambda = asCallable(value)
    if (lambda) {
      // only an ambiguous simple id ({{foo}}) receives the options object
      return invoked(lambda.call(frame.context, buildHelperOptions(name, {}, frame)))
    }
    if (value == null) {
      return runCall(noArgs, missingHelper(frame, 'helperMissing'), name, frame)
    }
    return value
  }
}

// mirrors the mustache half of upstream's classifySexpr. Only the registry is
// unknown at build time, so each shape gets its own closure.
function buildExpression (node: ExpressionHolder, scopes: BlockParamScopes): ValueFn {
  const rawPath = normalizePath(node.path)
  const call = planCall(node.params || [], node.hash, scopes)

  if (rawPath.type === 'SubExpression') {
    return buildSubExpressionCall(rawPath as Hbs.SubExpression, call, scopes)
  }

  const plan = planPath(rawPath as Hbs.PathExpression, scopes)
  const isBlockParam = plan.simple && plan.blockParam !== null
  const name = plan.simple ? plan.parts[0] : null

  if (AST.helpers.helperExpression(node) && !isBlockParam) {
    return buildCall(plan, call, name)
  }
  if (plan.simple && !isBlockParam) {
    return buildAmbiguous(plan, name)
  }
  return buildLookup(plan)
}

const noArgs: CallPlan = { params: [], hashKeys: [], hashValues: [] }

// ---------------------------------------------------------------------------
// Program bodies
// ---------------------------------------------------------------------------

interface InlineDefinition {
  name: string;
  body: NodeFn;
}

interface BuiltProgram {
  render: NodeFn;
  inlines: InlineDefinition[];
  // false when nothing below reads `../`, which lets the fn skip pushing its
  // context onto the depths stack
  usesDepths: boolean;
}

// build-time only. Every path goes through planPath, so reporting upward from
// there cannot miss one, which a separate AST walk could.
let sawDepthedPath = false

// a Program sits at exactly one position in the AST, so its enclosing block
// param scopes are fixed and the built tree can be cached on the node
const builtPrograms = new WeakMap<Hbs.Program, BuiltProgram>()

// a body of only content and comments can never vary, so it folds to one string
function foldContent (body: StatementNode[]): string | null {
  let text = ''
  for (const node of body) {
    if (node.type === 'ContentStatement') {
      text += node.value
    } else if (node.type !== 'CommentStatement') {
      return null
    }
  }
  return text
}

function buildRender (
  body: StatementNode[],
  scopes: BlockParamScopes,
  inlines: InlineDefinition[]
): NodeFn {
  const children: NodeFn[] = []
  // content separated only by a node that renders nothing, a comment or an
  // {{#*inline}} block, still renders back to back, so the run folds to one
  // closure
  let text = ''
  const flushText = (): void => {
    if (text) {
      const value = text
      children.push(() => value)
      text = ''
    }
  }

  for (const node of body) {
    if (node.type === 'ContentStatement') {
      text += node.value
      continue
    }
    const child = buildStatement(node, scopes)
    if (!child) {
      continue
    }
    flushText()
    children.push(child)
  }
  flushText()

  const renderBody: NodeFn = (frame) => renderAll(children, frame)
  return inlines.length
    ? (frame) => renderBody(withInlinePartials(frame, inlines))
    : renderBody
}

function buildProgram (program: Hbs.Program, outerScopes: BlockParamScopes): BuiltProgram {
  const cached = builtPrograms.get(program)
  if (cached) {
    // a cached subtree still has to tell its enclosing one what it uses
    sawDepthedPath = sawDepthedPath || cached.usesDepths
    return cached
  }

  // this body starts clean, and the enclosing one is restored below
  const outerSaw = sawDepthedPath
  sawDepthedPath = false

  // `as |a b|` introduces a scope for the body, matching what its ProgramFn
  // pushes onto frame.blockParamValues
  const scopes: BlockParamScopes =
    program.blockParams && program.blockParams.length
      ? [program.blockParams, ...outerScopes]
      : outerScopes

  const inlines = buildInlineDefinitions(program, scopes)
  const body = (program.body || []) as StatementNode[]
  // inline partials make the body frame-dependent, so it cannot fold
  const folded = inlines.length ? null : foldContent(body)

  // built before the flag is read, since planning the body's paths is what
  // sets it
  const render: NodeFn = folded !== null
    ? () => folded
    : buildRender(body, scopes, inlines)

  const usesDepths = sawDepthedPath
  sawDepthedPath = outerSaw || usesDepths

  const built: BuiltProgram = { render, inlines, usesDepths }

  builtPrograms.set(program, built)
  return built
}

// visible inside the program that defines them, and from a {{#> partial}} block
// to the called partial, so they are kept alongside the render fn
function buildInlineDefinitions (
  program: Hbs.Program | null,
  scopes: BlockParamScopes
): InlineDefinition[] {
  if (!program || !program.body) {
    return []
  }
  const definitions: InlineDefinition[] = []
  for (const node of program.body as Hbs.Node[]) {
    if (
      node.type !== 'DecoratorBlock' ||
      (node as Hbs.DecoratorBlock).path.original !== 'inline'
    ) {
      continue
    }
    const decorator = node as Hbs.DecoratorBlock
    const nameNode = decorator.params[0]
    // upstream evaluates decorator args at runtime.
    // Only literals here.
    if (!nameNode || nameNode.type !== 'StringLiteral') {
      throw new Exception('Inline partial names must be string literals', decorator)
    }
    definitions.push({
      name: (nameNode as Hbs.StringLiteral).value,
      body: buildProgram(decorator.program, scopes).render,
    })
  }
  return definitions
}

// the closures are made per invocation, since each captures the live frame
function withInlinePartials (frame: Frame, inlines: InlineDefinition[]): Frame {
  const partials: Record<string, Partial> = { ...frame.partials }
  for (const inline of inlines) {
    partials[inline.name] = ((ctx: unknown, opts: PartialCallOptions = {}) =>
      settle(inline.body(derive(
        frame, ctx, opts.data || frame.data, frame.depths,
        opts.partials ? { ...partials, ...opts.partials } : partials,
        frame.blockParamValues
      )))) as PartialFn
  }
  return derive(
    frame, frame.context, frame.data, frame.depths, partials, frame.blockParamValues
  )
}

// a fn invoked as @partial-block from a scope carrying a different one must
// still resolve to the block it was created for, or nested chains recurse
// forever
function restorePartialBlock (data: DataFrame, frame: Frame): DataFrame {
  const captured = frame.data ? frame.data['partial-block'] : undefined
  if (data === frame.data || !data || data['partial-block'] === captured) {
    return data
  }
  const restored = createFrame(data)
  restored['partial-block'] = captured
  return restored
}

// a factory for the `fn`/`inverse` handed to a block helper. The body is
// built once.
// Only the per-invocation frame is new.
function buildProgramFn (
  program: Hbs.Program,
  scopes: BlockParamScopes
): (frame: Frame) => ProgramFn {
  const built = buildProgram(program, scopes)
  const declared = program.blockParams ? program.blockParams.length : 0
  // depths exists only to answer `../`, so when nothing below asks, the copy
  // per invocation is one wasted array per loop iteration
  const usesDepths = built.usesDepths

  return (frame) => {
    const fn = ((context?: unknown, fnOptions: ProgramFnOptions = {}): string | Promise<string> => {
      const blockParamValues = declared
        ? [fnOptions.blockParams || emptyValues, ...frame.blockParamValues]
        : frame.blockParamValues

      const data = restorePartialBlock(fnOptions.data || frame.data, frame)

      return settle(built.render(derive(
        frame,
        context,
        data,
        // loose, matching wrapProgram upstream. It matters: iterating a one
        // element array binds the item, and `1 != [1]` is false, so upstream
        // pushes no level there and every `../` below counts one less.
        usesDepths && context != frame.depths[0]
          ? [context, ...frame.depths]
          : frame.depths,
        frame.partials,
        blockParamValues
      )))
    }) as ProgramFn

    fn.blockParams = declared
    return fn
  }
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------

// no ContentStatement case.
// buildRender, the only caller, accumulates content itself so that a run of it
// separated by comments folds to one closure.
function buildStatement (node: StatementNode, scopes: BlockParamScopes): NodeFn | null {
  switch (node.type) {
    case 'MustacheStatement':
      return buildMustache(node, scopes)
    case 'BlockStatement':
      return buildBlock(node, scopes)
    case 'PartialStatement': {
      const plan = planPartial(node, scopes)
      return (frame) => runPartial(plan, frame)
    }
    case 'PartialBlockStatement':
      return buildPartialBlock(node, scopes)
    case 'DecoratorBlock':
    case 'Decorator':
    case 'CommentStatement':
      return null
    default:
      // thrown when reached, so an unknown node in a dead branch stays harmless
      return () => {
        throw new Exception(
          'Unknown node type: ' + (node as Hbs.Node).type,
          node as Hbs.Node
        )
      }
  }
}

function buildMustache (node: Hbs.MustacheStatement, scopes: BlockParamScopes): NodeFn {
  const value = buildExpression(node, scopes)
  // chain inlined, since neither callback can return a Pending, so its unwrap
  // is dead and the sync path is left with just the instanceof
  if (node.escaped) {
    return (frame) => {
      const result = value(frame)
      return result instanceof Pending
        ? new Pending(result.promise.then(escapeExpression))
        : escapeExpression(result)
    }
  }
  return (frame) => {
    const result = value(frame)
    return result instanceof Pending
      ? new Pending(result.promise.then(stringify))
      : stringify(result)
  }
}

// every output that is not escaped. A SafeString reaches its toString here.
// Only escapeExpression, on the `{{x}}` path, checks toHTML.
function stringify (value: unknown): string {
  return value != null ? String(value) : ''
}

// everything about a block reference that is fixed at build time
interface BlockPlan {
  plan: PathPlan;
  call: CallPlan;
  name: string;
  // a simple id that is not a block param, so it may name a helper and its
  // lambda receives the options object
  ambiguous: boolean;
}

// no params, so the value is a lambda or plain data and blockHelperMissing
// decides what the block means. Only an ambiguous simple id ({{#foo}}) gets the
// options object.
// Every other lambda is called with nothing.
function runImplicitBlock (
  block: BlockPlan,
  frame: Frame,
  resolved: unknown,
  fn: ProgramFn,
  inverse: ProgramFn
): unknown {
  return chain(runHash(block.call, frame), (hash) => {
    const options = buildHelperOptions(
      block.name, hash, frame, fn, inverse
    )
    const lambda = asCallable(resolved)
    const lambdaResult = lambda
      ? invoked(block.ambiguous
        ? lambda.call(frame.context, options)
        : lambda.call(frame.context))
      : resolved

    return chain(lambdaResult, (result) => invoked(
      missingHelper(frame, 'blockHelperMissing').call(frame.context, result, options)
    ))
  })
}

function buildBlock (node: Hbs.BlockStatement, scopes: BlockParamScopes): NodeFn {
  // the grammar allows a literal block path (`{{#true}}`), even though the
  // upstream type says BlockStatement.path is always a PathExpression
  const rawPath = normalizePath(
    node.path as unknown as Hbs.PathExpression | Hbs.SubExpression | Hbs.Literal
  ) as Hbs.PathExpression

  const plan = planPath(rawPath, scopes)
  const isBlockParam = plan.simple && plan.blockParam !== null
  const hasParams = !isBlockParam && AST.helpers.helperExpression(node)
  const block: BlockPlan = {
    plan,
    call: planCall(node.params, node.hash, scopes),
    // the grammar rejects a subexpression here and normalizePath rewrote any
    // literal, so the path is always a PathExpression and always has a name
    name: plan.original,
    ambiguous: plan.simple && !isBlockParam,
  }

  const makeFn = node.program ? buildProgramFn(node.program, scopes) : null
  const makeInverse = node.inverse ? buildProgramFn(node.inverse, scopes) : null

  // one closure rather than a ValueFn wrapped in a stringifying NodeFn, which
  // cost a call per invocation. chain is inlined for the same reason.
  return (frame) => {
    const fn = makeFn ? makeFn(frame) : noopProgram
    const inverse = makeInverse ? makeInverse(frame) : noopProgram

    // the registry is only consulted for simple ids.
    // Pathed, depthed and scoped names always resolve from the context.
    const helper = block.ambiguous ? lookupHelper(frame, block.name) : undefined

    let result: unknown
    if (helper) {
      result = runCall(block.call, helper, block.name, frame, fn, inverse)
    } else {
      // resolved before the hash, matching the order params are evaluated in
      const resolved = resolvePlan(plan, frame)
      result = hasParams
        ? runCall(
          block.call,
          asCallable(resolved) || missingHelper(frame, 'helperMissing'),
          block.name,
          frame,
          fn,
          inverse
        )
        : runImplicitBlock(block, frame, resolved, fn, inverse)
    }

    return result instanceof Pending
      ? new Pending(result.promise.then(stringify))
      : stringify(result)
  }
}

// async-safe replacement for the vendored `each`
function nativeEach (this: unknown, ...args: unknown[]): unknown {
  const context = args[0]
  const options = asHelperOptions(args[1])
  if (!options) {
    throw new Exception('Must pass iterator to #each')
  }
  const fn = options.fn || noopProgram
  const inverse = options.inverse || noopProgram
  const iterable = asCallable(context)
  return chain(
    iterable ? invoked(iterable.call(this)) : context,
    (resolved) => eachOver(resolved, this, options.data, fn, inverse)
  )
}

// how to walk whatever `{{#each}}` was handed. `count` is slots, not values, so
// a sparse array counts its holes and the inverse stays unrun.
interface Walker {
  // non-array iterables are materialized, so `context[field]` resolves for a
  // block param
  context: unknown;
  count: number;
  fieldAt: (i: number) => unknown;
  valueAt: (i: number) => unknown;
  present: (i: number) => boolean;
}

const alwaysPresent = () => true

// only a sparse array has holes, so `present` defaults to true
function walker (
  context: unknown,
  count: number,
  fieldAt: (i: number) => unknown,
  valueAt: (i: number) => unknown,
  present: (i: number) => boolean = alwaysPresent
): Walker {
  return { context, count, fieldAt, valueAt, present }
}

// null for a non-object, so there is no walker whose accessors are never called
function walkerFor (context: unknown): Walker | null {
  if (!context || typeof context !== 'object') {
    return null
  }

  if (isMap(context)) {
    const entries = [...context]
    return walker(context, entries.length, (i) => entries[i][0], (i) => entries[i][1])
  }

  if (isSet(context)) {
    const values = [...context]
    return walker(context, values.length, (i) => i, (i) => values[i])
  }

  if (isArray(context) || (context as Record<symbol, unknown>)[Symbol.iterator]) {
    const arr = (isArray(context)
      ? context
      : Array.from(context as Iterable<unknown>)) as unknown[]
    return walker(arr, arr.length, (i) => i, (i) => arr[i], (i) => i in arr)
  }

  const obj = context as Record<string, unknown>
  const keys = Object.keys(obj)
  return walker(context, keys.length, (i) => keys[i], (i) => obj[keys[i]])
}

function eachOver (
  context: unknown,
  self: unknown,
  parentData: DataFrame,
  fn: ProgramFn,
  inverse: ProgramFn
): unknown {
  const walker = walkerFor(context)
  if (!walker || walker.count === 0) {
    return chain(invoked(inverse(self)), stringify)
  }
  const count = walker.count

  const data = createFrame(parentData)
  // a body without `as |x y|` ignores fnOptions.blockParams, so skip building
  // the array and the context read that fills it
  const wantsBlockParams = !!fn.blockParams
  // one options object reused across iterations, since a program reads it on
  // call and retains only the blockParams array
  const iterOptions: ProgramFnOptions = wantsBlockParams
    ? { data, blockParams: undefined }
    : { data }

  let ret = ''

  const step = (i: number): unknown => {
    if (!walker.present(i)) {
      return ''
    }
    const field = walker.fieldAt(i)
    data.key = field
    data.index = i
    data.first = i === 0
    data.last = i === count - 1
    if (wantsBlockParams) {
      iterOptions.blockParams = [
        (walker.context as Record<string, unknown>)[field as string],
        field,
      ]
    }
    return invoked(fn(walker.valueAt(i), iterOptions))
  }

  const pending = runFrom(0, count, step, (_i, piece) => { ret += (piece as string) || '' })
  return pending ? new Pending(pending.promise.then(() => ret)) : ret
}

// ---------------------------------------------------------------------------
// Source cache
// ---------------------------------------------------------------------------

// parsing dominates a render, so ASTs are cached on their source text: for a
// template passed as a string, and for a string partial (GH-1598), which
// callers commonly hand over in a map they rebuild every render. Bounded
// because the sources are user data: the limit counts characters, an entry
// retains far more.
interface CacheEntry {
  ast: Hbs.Program;
  // only a source used as a partial needs one, so it is made on first use
  fn?: PartialFn;
}

const sourceCacheLimit = 64 * 1024
const sourceCache = new Map<string, CacheEntry>()
let sourceCacheChars = 0

function cachedParse (source: string): CacheEntry {
  const cached = sourceCache.get(source)
  if (cached) {
    // reinserted, so eviction is least-recently-used
    sourceCache.delete(source)
    sourceCache.set(source, cached)
    return cached
  }

  const entry: CacheEntry = { ast: parse(source) }
  sourceCache.set(source, entry)
  sourceCacheChars += source.length
  // size > 1 keeps the entry just added, even if it alone exceeds the limit
  while (sourceCacheChars > sourceCacheLimit && sourceCache.size > 1) {
    const oldest = sourceCache.keys().next().value as string
    sourceCache.delete(oldest)
    sourceCacheChars -= oldest.length
  }
  return entry
}

// only the AST is captured, so the cached fn holds no state from whichever
// render compiled it
function compileStringPartial (source: string): PartialFn {
  const entry = cachedParse(source)
  if (!entry.fn) {
    const ast = entry.ast
    entry.fn = (context, options = {}) =>
      briskbars(ast, context, options as RuntimeOptions)
  }
  return entry.fn
}

// ---------------------------------------------------------------------------
// Partials
// ---------------------------------------------------------------------------

interface PartialPlan {
  node: Hbs.PartialStatement | Hbs.PartialBlockStatement;
  // present when the name is a subexpression, so it resolves per render
  nameFn: ValueFn | null;
  // empty when nameFn is set, which is the only case that leaves it unread
  staticName: string;
  paramCount: number;
  contextFn: ValueFn | null;
  hash: CallPlan;
  hasHash: boolean;
  indent: string;
}

function planPartial (
  node: Hbs.PartialStatement | Hbs.PartialBlockStatement,
  scopes: BlockParamScopes
): PartialPlan {
  const nameNode = node.name as
    Hbs.PathExpression | Hbs.SubExpression | Hbs.Literal
  const params = node.params || []
  // a subexpression name is the one shape with no `original` to read. The rest,
  // PathExpression for `{{> foo}}` and `{{> [a b]}}`, StringLiteral for
  // `{{> "a b"}}` and NumberLiteral for `{{> 42}}`, all carry one, so String()
  // covers the numeric case rather than leaving a number typed as a string.
  const dynamic = nameNode.type === 'SubExpression'
  return {
    node,
    nameFn: dynamic ? buildExpression(nameNode as Hbs.SubExpression, scopes) : null,
    staticName: dynamic
      ? ''
      : String((nameNode as { original: unknown }).original),
    paramCount: params.length,
    contextFn: params.length > 0 ? buildValue(params[0], scopes) : null,
    hash: planCall(undefined, node.hash, scopes),
    hasHash: !!node.hash,
    indent: (node as Hbs.PartialStatement).indent || '',
  }
}

// the name can come from the template or, for `{{> (dynamic)}}`, from data, so
// it gets the same guard findHelper puts on the helper registry. Without it
// `{{> toString}}` reaches Object.prototype and calls what it finds there.
function findPartial (partials: PartialsMap, name: string): Partial | undefined {
  return Object.prototype.hasOwnProperty.call(partials, name)
    ? partials[name]
    : undefined
}

// looks the partial up and, if it is source text, compiles it. env.compile is
// never consulted.
// In real Handlebars it runs the eval-based compiler this interpreter avoids.
function resolvePartialFn (frame: Frame, partialName: string): PartialFn {
  let partial: Partial | undefined = partialName === '@partial-block'
    ? frame.data && (frame.data['partial-block'] as Partial | undefined)
    : findPartial(frame.partials, partialName)

  if (typeof partial === 'string') {
    try {
      partial = compileStringPartial(partial)
    } catch (err) {
      const detail = err instanceof Error ? err.message : String(err)
      const exception = new Exception(
        'The partial ' + partialName + ' could not be compiled: ' + detail
      )
      exception.cause = err
      throw exception
    }
  }

  if (!partial) {
    throw new Exception('The partial "' + partialName + '" could not be found')
  }
  return partial as PartialFn
}

// a hash merges into the context the partial renders against, and `indent`
// re-indents whatever it produced
function callPartial (plan: PartialPlan, frame: Frame, partialFn: PartialFn): Rendered {
  return chain(
    plan.contextFn ? plan.contextFn(frame) : frame.context,
    (context) => chain(plan.hasHash ? runHash(plan.hash, frame) : null, (hash) => {
      const target = hash
        ? extend({}, context, hash)
        : context

      const callOpts: PartialCallOptions = {
        ...frame.options,
        helpers: frame.helpers,
        partials: frame.partials,
        data: frame.data,
      }

      return chain(invoked(partialFn(target, callOpts)), (result) =>
        indentResult((result as string) || '', plan.indent))
    })
  )
}

// `resolvedName` skips the lookup for a partial block, which already resolved it
function runPartial (plan: PartialPlan, frame: Frame, resolvedName?: string): Rendered {
  const named = (partialName: string): Rendered => {
    if (plan.paramCount > 1) {
      throw new Exception(
        'Unsupported number of partial arguments: ' + plan.paramCount,
        plan.node
      )
    }
    return callPartial(plan, frame, resolvePartialFn(frame, partialName))
  }

  if (resolvedName !== undefined) {
    return named(resolvedName)
  }
  if (!plan.nameFn) {
    return named(plan.staticName)
  }
  return chain(plan.nameFn(frame), (name) => named(name as string))
}

function indentResult (result: string, indent: string): string {
  if (!indent || !result) {
    return result
  }
  // every line, except the empty one a trailing newline leaves behind. `$` has
  // no `m` flag here, so it only matches a newline that ends the string.
  return indent + result.replace(/\n(?!$)/g, '\n' + indent)
}

// the block's own body becomes @partial-block for the partial it calls, and any
// inline partials the block defines have to be visible there too
function partialBlockFrame (
  frame: Frame,
  fn: ProgramFn,
  inlines: InlineDefinition[]
): Frame {
  const data = createFrame(frame.data)
  data['partial-block'] = fn
  const partials = inlines.length
    ? withInlinePartials(frame, inlines).partials
    : frame.partials
  return derive(
    frame, frame.context, data, frame.depths, partials, frame.blockParamValues
  )
}

// {{#> missing}}body{{/missing}} renders its own body when the partial is absent
function renderDefaultBlock (plan: PartialPlan, frame: Frame, fn: ProgramFn): Rendered {
  return chain(
    plan.contextFn ? plan.contextFn(frame) : frame.context,
    (context) => chain(
      invoked(fn(context, { data: frame.data })),
      (result) => (result as string) || ''
    )
  )
}

function buildPartialBlock (
  node: Hbs.PartialBlockStatement,
  scopes: BlockParamScopes
): NodeFn {
  const plan = planPartial(node, scopes)
  const makeFn = node.program ? buildProgramFn(node.program, scopes) : null
  const blockInlines = node.program ? buildInlineDefinitions(node.program, scopes) : []

  // the name is always static here.
  // The parser matches a block's closing tag against the name's `original`,
  // which a subexpression does not have, so `{{#> (dynamic)}}` never parses.
  const partialName = plan.staticName

  return (frame) => {
    const fn = makeFn ? makeFn(frame) : noopProgram
    const childFrame = partialBlockFrame(frame, fn, blockInlines)

    // check existence with !== undefined ('' is a valid partial body)
    const exists = partialName !== '@partial-block' &&
      findPartial(childFrame.partials, partialName) !== undefined
    return exists
      ? runPartial(plan, childFrame, partialName)
      : renderDefaultBlock(plan, frame, fn)
  }
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

// a frame propagated from a parent render already carries @root, so it is used
// as-is.
// Anything else is a plain object the caller passed and gets wrapped.
function initData (context: unknown, data: unknown): DataFrame {
  if (
    !data ||
    typeof data !== 'object' ||
    !('root' in data)
  ) {
    data = data && typeof data === 'object' ? createFrame(data) : {};
    (data as DataFrame).root = context
  }
  return data as DataFrame
}

export default function briskbars (
  template: string | Hbs.Program,
  context: unknown,
  runtimeOptions: RuntimeOptions = {}
): string | Promise<string> {
  if (
    template == null ||
    (typeof template !== 'string' && template.type !== 'Program')
  ) {
    throw new Exception(
      'You must pass a string or Handlebars AST. You passed ' +
        template
    )
  }
  const ast = typeof template === 'string'
    ? cachedParse(template).ast
    : template

  // cached on the Program node, so the walk happens once per template
  const built = buildProgram(ast, emptyScopes)

  const data = initData(context, runtimeOptions.data)

  // neither map is copied, and neither is written to
  const helpers = (runtimeOptions.helpers || emptyHelpers) as HelpersMap
  const partials = (runtimeOptions.partials || emptyPartials) as PartialsMap

  return settle(built.render({
    context,
    data,
    depths: [context],
    helpers,
    partials,
    blockParamValues: [],
    lookupProperty: defaultLookupProperty,
    options: runtimeOptions,
  }))
}

